"Probá con otra palabra o quitá algún filtro.": "別の言葉で試すか、絞り込みを外してください。",
"Imprescindible": "必見",
"Vale la visita": "行く価値あり",
"Para curiosos": "好奇心旺盛な人に",
"Tocá un barrio para ver el detalle.": "地区をタップすると詳細が見られます。",
"Puntos de ayuda: ℹ️ información turística": "相談窓口：ℹ️ 観光案内",
"policía y denuncias": "警察と被害届",
